public void run()
{    
    METProcMetrics procMetrics = METProcMetrics::construct(METBatchLogOperation::DeliveryNotePostingAfterFinalization);
    procMetrics.beginTrace('Process started');

    using (METProcMetricsScope procMetricsScope = METProcMetricsScope::constructWithErrorHandling(procMetrics))
    {
        next run(); 

        procMetrics.endTrace();
    }
}
